<?php
declare(strict_types=1);
require_once __DIR__.'/includes/iniciar.php';
$cliente=exigir_cliente();$id=(int)($_GET['id']??0);
$st=$pdo->prepare("SELECT * FROM orders WHERE id=? AND customer_id=? LIMIT 1");$st->execute([$id,(int)$cliente['id']]);$pedido=$st->fetch();if(!$pedido){http_response_code(404);exit('Pedido não encontrado.');}
$it=$pdo->prepare("SELECT * FROM order_items WHERE order_id=? ORDER BY id");$it->execute([$id]);$items=$it->fetchAll();
$pf=$pdo->prepare("SELECT * FROM proformas WHERE order_id=? ORDER BY id DESC LIMIT 1");$pf->execute([$id]);$proforma=$pf->fetch();
$cv=$pdo->prepare("SELECT id FROM conversations WHERE order_id=? AND customer_id=? LIMIT 1");$cv->execute([$id,(int)$cliente['id']]);$conversation=$cv->fetch();
$tituloPagina='Pedido '.$pedido['order_number'];require __DIR__.'/includes/header-marketplace.php';
?>
<div class="container section"><div class="breadcrumbs"><a href="pedidos.php">Os meus pedidos</a> / <?=e($pedido['order_number'])?></div><h1 class="page-title">Pedido <?=e($pedido['order_number'])?></h1><?=cliente_flash_html()?><div class="two-col"><section><div class="panel" style="padding:20px;margin-bottom:18px"><div class="summary-row"><span>Estado</span><span class="status"><?=e($pedido['status'])?></span></div><div class="summary-row"><span>Data</span><strong><?=e($pedido['created_at'])?></strong></div><div class="summary-row"><span>Entrega</span><strong><?=e($pedido['delivery_address'])?>, <?=e($pedido['delivery_city']??'')?>, <?=e($pedido['delivery_province']??'')?></strong></div></div><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Quantidade</th><th>Preço unitário</th><th>Subtotal</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e($i['product_name'])?></td><td><?=e($i['quantity'])?> <?=e($i['unit']??'')?></td><td><?=money($i['unit_price'])?></td><td><?=money($i['subtotal'])?></td></tr><?php endforeach;?></tbody></table></div></section><aside class="summary"><h3>Resumo financeiro</h3><div class="summary-row"><span>Subtotal</span><strong><?=money($pedido['subtotal'])?></strong></div><div class="summary-row"><span>Entrega</span><strong><?=money($pedido['delivery_fee'])?></strong></div><div class="summary-row"><span>Desconto</span><strong><?=money($pedido['discount'])?></strong></div><div class="summary-row summary-total"><span>Total</span><strong><?=money($pedido['total'])?></strong></div><hr><h3>Documentos e conversa</h3><?php if($proforma):?><a class="btn-outline full" href="proforma.php?id=<?=(int)$proforma['id']?>">Ver proforma</a><?php else:?><p class="muted">A proforma ainda não está disponível.</p><?php endif;?><p></p><?php if($conversation):?><a class="btn full" href="chat.php?pedido=<?=$id?>">Abrir conversa</a><?php endif;?></aside></div></div>
